def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Extend each paired marker pattern by filling only the gap between adjacent
    # markers in a row or column; the demo establishes the inserted color as 2.
    for r in range(h):
        cols = [c for c, v in enumerate(g[r]) if v not in (8, 9)]
        for a, b in zip(cols, cols[1:]):
            if b - a > 1:
                for c in range(a + 1, b):
                    g[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] not in (8, 9)]
        for a, b in zip(rows, rows[1:]):
            if b - a > 1:
                for r in range(a + 1, b):
                    g[r][c] = 2
    return g
